if style.startswith("random"):
    suffix = style[len("random"):]
    if not suffix.isdigit():
        raise ValueError(
            f"random 风格后必须跟数字（如 random32、random64），收到: {suffix!r}"
        )
    return RandomStrategy(int(suffix))

